import type { Vec3 } from '../contracts/math';

export function requireId(id: string, what: string): string {
  const trimmed = typeof id === 'string' ? id.trim() : '';
  if (trimmed.length === 0) throw new Error(what + ' requires a non-empty id');
  return trimmed;
}

export function requireFinite(value: number, what: string): number {
  if (!Number.isFinite(value)) throw new Error(what + ' must be a finite number');
  return value;
}

export function requirePositive(value: number, what: string): number {
  if (!Number.isFinite(value) || value <= 0) throw new Error(what + ' must be a positive finite number');
  return value;
}

export function requireCount(value: number, what: string, min = 1): number {
  if (!Number.isInteger(value) || value < min) throw new Error(what + ' must be an integer of at least ' + min);
  return value;
}

export function requireVec3(value: Vec3, what: string): Vec3 {
  if (!value || !Number.isFinite(value.x) || !Number.isFinite(value.y) || !Number.isFinite(value.z)) {
    throw new Error(what + ' must be a finite vector');
  }
  return { x: value.x, y: value.y, z: value.z };
}
