import type { Quat, Vec3 } from '../contracts/math';

export const TWO_PI = Math.PI * 2;

const EPSILON = 1e-9;

export function normalizeAngle(angle: number): number {
  if (!Number.isFinite(angle)) throw new Error('Rotation angle must be a finite number');
  const wrapped = angle % TWO_PI;
  if (wrapped === 0) return 0;
  return wrapped < 0 ? wrapped + TWO_PI : wrapped;
}

export function normalizeAxis(axis: Vec3): Vec3 {
  const length = Math.hypot(axis.x, axis.y, axis.z);
  if (!Number.isFinite(length) || length < EPSILON) {
    throw new Error('Rotation axis must be a finite non-zero vector');
  }
  return { x: axis.x / length, y: axis.y / length, z: axis.z / length };
}

/** Deterministic rotor angle: only phase, speed and elapsed time decide it. */
export function angleAt(phase: number, speed: number, elapsedSeconds: number): number {
  return normalizeAngle(phase + speed * elapsedSeconds);
}

export function quaternionFromAxisAngle(axis: Vec3, angle: number): Quat {
  const unit = normalizeAxis(axis);
  const half = angle * 0.5;
  const sin = Math.sin(half);
  return { x: unit.x * sin, y: unit.y * sin, z: unit.z * sin, w: Math.cos(half) };
}

export function multiplyQuaternions(a: Quat, b: Quat): Quat {
  return {
    x: a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
    y: a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
    z: a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w,
    w: a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
  };
}

export function rotateVector(q: Quat, v: Vec3): Vec3 {
  const tx = 2 * (q.y * v.z - q.z * v.y);
  const ty = 2 * (q.z * v.x - q.x * v.z);
  const tz = 2 * (q.x * v.y - q.y * v.x);
  return {
    x: v.x + q.w * tx + q.y * tz - q.z * ty,
    y: v.y + q.w * ty + q.z * tx - q.x * tz,
    z: v.z + q.w * tz + q.x * ty - q.y * tx,
  };
}

export function crossProduct(a: Vec3, b: Vec3): Vec3 {
  return {
    x: a.y * b.z - a.z * b.y,
    y: a.z * b.x - a.x * b.z,
    z: a.x * b.y - a.y * b.x,
  };
}

/** Stable unit vector perpendicular to the axis; same axis always yields the same result. */
export function perpendicularAxis(axis: Vec3): Vec3 {
  const unit = normalizeAxis(axis);
  const candidate: Vec3 = Math.abs(unit.x) > 0.9 ? { x: 0, y: 1, z: 0 } : { x: 1, y: 0, z: 0 };
  const dot = candidate.x * unit.x + candidate.y * unit.y + candidate.z * unit.z;
  return normalizeAxis({
    x: candidate.x - unit.x * dot,
    y: candidate.y - unit.y * dot,
    z: candidate.z - unit.z * dot,
  });
}

/** Quaternion whose local X, Y and Z axes map onto the given orthonormal basis. */
export function quaternionFromBasis(xAxis: Vec3, yAxis: Vec3, zAxis: Vec3): Quat {
  const m00 = xAxis.x;
  const m10 = xAxis.y;
  const m20 = xAxis.z;
  const m01 = yAxis.x;
  const m11 = yAxis.y;
  const m21 = yAxis.z;
  const m02 = zAxis.x;
  const m12 = zAxis.y;
  const m22 = zAxis.z;
  const trace = m00 + m11 + m22;

  if (trace > 0) {
    const s = Math.sqrt(trace + 1) * 2;
    return { x: (m21 - m12) / s, y: (m02 - m20) / s, z: (m10 - m01) / s, w: 0.25 * s };
  }
  if (m00 > m11 && m00 > m22) {
    const s = Math.sqrt(1 + m00 - m11 - m22) * 2;
    return { x: 0.25 * s, y: (m01 + m10) / s, z: (m02 + m20) / s, w: (m21 - m12) / s };
  }
  if (m11 > m22) {
    const s = Math.sqrt(1 + m11 - m00 - m22) * 2;
    return { x: (m01 + m10) / s, y: 0.25 * s, z: (m12 + m21) / s, w: (m02 - m20) / s };
  }
  const s = Math.sqrt(1 + m22 - m00 - m11) * 2;
  return { x: (m02 + m20) / s, y: (m12 + m21) / s, z: 0.25 * s, w: (m10 - m01) / s };
}
