import type { Quat, Vec3 } from '../contracts/math';
import {
  TWO_PI,
  crossProduct,
  multiplyQuaternions,
  normalizeAxis,
  perpendicularAxis,
  quaternionFromAxisAngle,
  quaternionFromBasis,
  rotateVector,
} from './rotation';
import type { ObstaclePart } from './types';
import { requireCount, requireFinite, requirePositive } from './validation';

export interface RotationFrame {
  axis: Vec3;
  radial: Vec3;
  tangent: Vec3;
  rotation: Quat;
}

/** Local frame of a rotor: part length runs along `radial`, part depth along `axis`. */
export function rotationFrame(axis: Vec3): RotationFrame {
  const unit = normalizeAxis(axis);
  const radial = perpendicularAxis(unit);
  const tangent = crossProduct(radial, unit);
  return { axis: unit, radial, tangent, rotation: quaternionFromBasis(radial, unit, tangent) };
}

export interface RadialPartsOptions {
  axis: Vec3;
  count: number;
  /** Radial length of one arm, measured from the hub edge outwards. */
  length: number;
  /** Arm size across the rotation plane. */
  width: number;
  /** Arm size along the rotation axis. */
  depth: number;
  innerRadius?: number;
  offsetAngle?: number;
  namePrefix?: string;
  color?: number;
  restitution?: number;
}

export function buildRadialParts(options: RadialPartsOptions): ObstaclePart[] {
  const count = requireCount(options.count, 'Radial part count', 1);
  const length = requirePositive(options.length, 'Radial part length');
  const width = requirePositive(options.width, 'Radial part width');
  const depth = requirePositive(options.depth, 'Radial part depth');
  const innerRadius = Math.max(0, requireFinite(options.innerRadius ?? 0, 'Radial part inner radius'));
  const offsetAngle = requireFinite(options.offsetAngle ?? 0, 'Radial part offset angle');
  const frame = rotationFrame(options.axis);
  const prefix = options.namePrefix ?? 'arm';
  const distance = innerRadius + length / 2;
  const parts: ObstaclePart[] = [];

  for (let index = 0; index < count; index += 1) {
    const angle = offsetAngle + (TWO_PI * index) / count;
    const spin = quaternionFromAxisAngle(frame.axis, angle);
    parts.push({
      name: prefix + '-' + (index + 1),
      size: { x: length, y: depth, z: width },
      offset: rotateVector(spin, {
        x: frame.radial.x * distance,
        y: frame.radial.y * distance,
        z: frame.radial.z * distance,
      }),
      rotation: multiplyQuaternions(spin, frame.rotation),
      color: options.color,
      restitution: options.restitution,
    });
  }
  return parts;
}

export interface HubPartOptions {
  axis: Vec3;
  radius: number;
  depth: number;
  name?: string;
  color?: number;
  restitution?: number;
}

export function buildHubPart(options: HubPartOptions): ObstaclePart {
  const radius = requirePositive(options.radius, 'Hub radius');
  const depth = requirePositive(options.depth, 'Hub depth');
  const frame = rotationFrame(options.axis);
  return {
    name: options.name ?? 'hub',
    size: { x: radius * 2, y: depth, z: radius * 2 },
    offset: { x: 0, y: 0, z: 0 },
    rotation: frame.rotation,
    color: options.color,
    restitution: options.restitution,
  };
}
