import * as THREE from 'three';
import type { Quat, Vec3 } from '../contracts/math';
import { angleAt, normalizeAngle, normalizeAxis, quaternionFromAxisAngle } from './rotation';
import type { ObstacleBody, ObstacleBodyFactory, ObstacleColliderDescriptor, ObstaclePart } from './types';
import { requireFinite, requireId, requireVec3 } from './validation';

export interface RotatingObstacleOptions {
  id: string;
  position: Vec3;
  /** Rotation axis in world space; defaults to the vertical axis. */
  axis?: Vec3;
  /** Angular velocity in radians per second; negative spins the other way. */
  speed?: number;
  /** Starting angle in radians. */
  phase?: number;
  enabled?: boolean;
  restitution?: number;
  color?: number;
  scene?: THREE.Scene;
  physics?: ObstacleBodyFactory;
}

const DEFAULT_AXIS: Vec3 = { x: 0, y: 1, z: 0 };
const DEFAULT_SPEED = 1;
const DEFAULT_RESTITUTION = 0.45;
const DEFAULT_COLOR = 0x9fb0c3;

/**
 * Shared lifecycle of every rotating obstacle: visual group, kinematic colliders
 * and a deterministic angle derived from phase, speed and accumulated time.
 */
export abstract class RotatingObstacle {
  readonly kind: string;
  readonly id: string;
  readonly axis: Vec3;
  readonly restitution: number;
  readonly parts: readonly ObstaclePart[];
  readonly object3d: THREE.Group;
  /** Distance from the rotation centre to the outer edge of the widest part. */
  readonly reach: number;

  private readonly initialPhase: number;
  private readonly initialSpeed: number;
  private readonly materials: THREE.Material[] = [];
  private speedValue: number;
  private phaseValue: number;
  private angleValue: number;
  private elapsedValue = 0;
  private enabledValue: boolean;
  private disposedValue = false;
  private bodyValue: ObstacleBody | null = null;
  private sceneValue: THREE.Scene | null = null;

  protected constructor(kind: string, options: RotatingObstacleOptions, parts: readonly ObstaclePart[]) {
    if (parts.length === 0) throw new Error(kind + ' requires at least one part');
    this.kind = kind;
    this.id = requireId(options.id, kind);
    this.axis = normalizeAxis(options.axis ?? DEFAULT_AXIS);
    this.parts = parts.map((part) => ({ ...part }));
    this.restitution = requireFinite(options.restitution ?? DEFAULT_RESTITUTION, kind + ' restitution');
    this.initialSpeed = requireFinite(options.speed ?? DEFAULT_SPEED, kind + ' speed');
    this.initialPhase = requireFinite(options.phase ?? 0, kind + ' phase');
    this.speedValue = this.initialSpeed;
    this.phaseValue = this.initialPhase;
    this.angleValue = normalizeAngle(this.initialPhase);
    this.enabledValue = options.enabled ?? true;
    this.reach = this.parts.reduce(
      (max, part) => Math.max(max, Math.hypot(part.offset.x, part.offset.y, part.offset.z) + part.size.x / 2),
      0,
    );

    const position = requireVec3(options.position, kind + ' position');
    const color = options.color ?? DEFAULT_COLOR;
    this.object3d = new THREE.Group();
    this.object3d.name = kind + ':' + this.id;
    this.object3d.position.set(position.x, position.y, position.z);
    for (const part of this.parts) {
      const material = new THREE.MeshStandardMaterial({
        color: part.color ?? color,
        roughness: 0.62,
        metalness: 0.12,
      });
      this.materials.push(material);
      const mesh = new THREE.Mesh(new THREE.BoxGeometry(part.size.x, part.size.y, part.size.z), material);
      mesh.name = part.name;
      mesh.position.set(part.offset.x, part.offset.y, part.offset.z);
      mesh.quaternion.set(part.rotation.x, part.rotation.y, part.rotation.z, part.rotation.w);
      mesh.castShadow = true;
      mesh.receiveShadow = true;
      this.object3d.add(mesh);
    }
    this.object3d.visible = this.enabledValue;

    if (options.physics) this.bindPhysics(options.physics);
    this.applyRotation();
    if (options.scene) this.attach(options.scene);
  }

  get angle(): number { return this.angleValue; }
  get rotation(): Quat { return quaternionFromAxisAngle(this.axis, this.angleValue); }
  get speed(): number { return this.speedValue; }
  get phase(): number { return this.phaseValue; }
  get elapsed(): number { return this.elapsedValue; }
  get enabled(): boolean { return this.enabledValue; }
  get disposed(): boolean { return this.disposedValue; }
  get body(): ObstacleBody | null { return this.bodyValue; }

  get position(): Vec3 {
    const p = this.object3d.position;
    return { x: p.x, y: p.y, z: p.z };
  }

  colliderDescriptors(): ObstacleColliderDescriptor[] {
    return this.parts.map((part) => ({
      name: part.name,
      halfExtents: { x: part.size.x / 2, y: part.size.y / 2, z: part.size.z / 2 },
      offset: { ...part.offset },
      rotation: { ...part.rotation },
      restitution: part.restitution ?? this.restitution,
    }));
  }

  bindPhysics(factory: ObstacleBodyFactory): ObstacleBody {
    if (this.disposedValue) throw new Error(this.kind + ' ' + this.id + ' is disposed');
    this.bodyValue?.dispose();
    const body = factory.createBody(this.id, this.position, this.colliderDescriptors());
    this.bodyValue = body;
    body.setEnabled(this.enabledValue);
    body.setRotation(this.rotation);
    return body;
  }

  attach(scene: THREE.Scene): void {
    if (this.disposedValue || this.sceneValue === scene) return;
    this.detach();
    scene.add(this.object3d);
    this.sceneValue = scene;
  }

  detach(): void {
    this.sceneValue?.remove(this.object3d);
    this.sceneValue = null;
  }

  /** Advances the rotor; ignores non-positive or non-finite steps. */
  update(deltaSeconds: number): number {
    if (this.disposedValue || !this.enabledValue) return this.angleValue;
    if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return this.angleValue;
    this.elapsedValue += deltaSeconds;
    this.angleValue = angleAt(this.phaseValue, this.speedValue, this.elapsedValue);
    this.applyRotation();
    return this.angleValue;
  }

  /** Changes angular velocity without teleporting the rotor. */
  setSpeed(speed: number): void {
    const next = requireFinite(speed, this.kind + ' speed');
    this.phaseValue = this.angleValue - next * this.elapsedValue;
    this.speedValue = next;
  }

  setEnabled(enabled: boolean): void {
    if (this.disposedValue) return;
    this.enabledValue = enabled;
    this.object3d.visible = enabled;
    this.bodyValue?.setEnabled(enabled);
  }

  /** Restores the configured phase and speed, as used when a hole restarts. */
  reset(): void {
    if (this.disposedValue) return;
    this.elapsedValue = 0;
    this.phaseValue = this.initialPhase;
    this.speedValue = this.initialSpeed;
    this.angleValue = normalizeAngle(this.initialPhase);
    this.applyRotation();
  }

  dispose(): void {
    if (this.disposedValue) return;
    this.disposedValue = true;
    this.detach();
    this.bodyValue?.dispose();
    this.bodyValue = null;
    for (const child of this.object3d.children) {
      if (child instanceof THREE.Mesh) child.geometry.dispose();
    }
    for (const material of this.materials) material.dispose();
    this.materials.length = 0;
    this.object3d.clear();
  }

  private applyRotation(): void {
    const q = quaternionFromAxisAngle(this.axis, this.angleValue);
    this.object3d.quaternion.set(q.x, q.y, q.z, q.w);
    this.bodyValue?.setRotation(q);
  }
}
