import type { Vec3 } from '../contracts/math';
import { buildHubPart, rotationFrame } from './parts';
import { RotatingObstacle, type RotatingObstacleOptions } from './RotatingObstacle';
import type { ObstaclePart } from './types';
import { requireFinite, requirePositive } from './validation';

export interface RotatingBarOptions extends RotatingObstacleOptions {
  /** Full length of the bar across the rotation plane. */
  length?: number;
  /** Bar thickness across the rotation plane. */
  width?: number;
  /** Bar size along the rotation axis. */
  depth?: number;
  /** Radius of the optional centre hub; 0 disables it. */
  hubRadius?: number;
}

const DEFAULT_AXIS: Vec3 = { x: 0, y: 1, z: 0 };
const DEFAULT_LENGTH = 4;
const DEFAULT_WIDTH = 0.4;
const DEFAULT_DEPTH = 0.3;

function buildBarParts(options: RotatingBarOptions): ObstaclePart[] {
  const length = requirePositive(options.length ?? DEFAULT_LENGTH, 'RotatingBar length');
  const width = requirePositive(options.width ?? DEFAULT_WIDTH, 'RotatingBar width');
  const depth = requirePositive(options.depth ?? DEFAULT_DEPTH, 'RotatingBar depth');
  const hubRadius = Math.max(0, requireFinite(options.hubRadius ?? 0, 'RotatingBar hub radius'));
  const axis = options.axis ?? DEFAULT_AXIS;
  const frame = rotationFrame(axis);
  const parts: ObstaclePart[] = [{
    name: 'bar',
    size: { x: length, y: depth, z: width },
    offset: { x: 0, y: 0, z: 0 },
    rotation: frame.rotation,
  }];
  if (hubRadius > 0) parts.push(buildHubPart({ axis, radius: hubRadius, depth: depth * 1.5 }));
  return parts;
}

/** Single sweeping bar: the simplest rotor, used as a blocker across a fairway. */
export class RotatingBar extends RotatingObstacle {
  readonly length: number;
  readonly width: number;
  readonly depth: number;
  readonly hubRadius: number;

  constructor(options: RotatingBarOptions) {
    super('rotating-bar', options, buildBarParts(options));
    this.length = options.length ?? DEFAULT_LENGTH;
    this.width = options.width ?? DEFAULT_WIDTH;
    this.depth = options.depth ?? DEFAULT_DEPTH;
    this.hubRadius = Math.max(0, options.hubRadius ?? 0);
  }
}
