import type { Vec3 } from '../contracts/math';
import { buildHubPart, buildRadialParts } from './parts';
import { RotatingObstacle, type RotatingObstacleOptions } from './RotatingObstacle';
import type { ObstaclePart } from './types';
import { requireCount, requirePositive } from './validation';

export interface WindmillOptions extends RotatingObstacleOptions {
  bladeCount?: number;
  /** Radial blade length, measured from the hub edge outwards. */
  bladeLength?: number;
  /** Blade size across the rotation plane. */
  bladeWidth?: number;
  /** Blade size along the rotation axis. */
  bladeDepth?: number;
  hubRadius?: number;
}

/** Windmills usually face the player, so they spin around the depth axis by default. */
const DEFAULT_AXIS: Vec3 = { x: 0, y: 0, z: 1 };
const DEFAULT_BLADE_COUNT = 4;
const DEFAULT_BLADE_LENGTH = 2.2;
const DEFAULT_BLADE_WIDTH = 0.8;
const DEFAULT_BLADE_DEPTH = 0.25;
const DEFAULT_HUB_RADIUS = 0.35;

interface WindmillShape {
  axis: Vec3;
  bladeCount: number;
  bladeLength: number;
  bladeWidth: number;
  bladeDepth: number;
  hubRadius: number;
}

function resolveShape(options: WindmillOptions): WindmillShape {
  return {
    axis: options.axis ?? DEFAULT_AXIS,
    bladeCount: requireCount(options.bladeCount ?? DEFAULT_BLADE_COUNT, 'Windmill blade count', 2),
    bladeLength: requirePositive(options.bladeLength ?? DEFAULT_BLADE_LENGTH, 'Windmill blade length'),
    bladeWidth: requirePositive(options.bladeWidth ?? DEFAULT_BLADE_WIDTH, 'Windmill blade width'),
    bladeDepth: requirePositive(options.bladeDepth ?? DEFAULT_BLADE_DEPTH, 'Windmill blade depth'),
    hubRadius: Math.max(0, options.hubRadius ?? DEFAULT_HUB_RADIUS),
  };
}

function buildWindmillParts(shape: WindmillShape): ObstaclePart[] {
  const parts = buildRadialParts({
    axis: shape.axis,
    count: shape.bladeCount,
    length: shape.bladeLength,
    width: shape.bladeWidth,
    depth: shape.bladeDepth,
    innerRadius: shape.hubRadius,
    namePrefix: 'blade',
  });
  if (shape.hubRadius > 0) {
    parts.push(buildHubPart({ axis: shape.axis, radius: shape.hubRadius, depth: shape.bladeDepth * 1.6 }));
  }
  return parts;
}

/** Classic mini-golf windmill: evenly spaced blades sweeping past the entry gap. */
export class Windmill extends RotatingObstacle {
  readonly bladeCount: number;
  readonly bladeLength: number;
  readonly bladeWidth: number;
  readonly bladeDepth: number;
  readonly hubRadius: number;

  constructor(options: WindmillOptions) {
    const shape = resolveShape(options);
    super('windmill', { ...options, axis: shape.axis }, buildWindmillParts(shape));
    this.bladeCount = shape.bladeCount;
    this.bladeLength = shape.bladeLength;
    this.bladeWidth = shape.bladeWidth;
    this.bladeDepth = shape.bladeDepth;
    this.hubRadius = shape.hubRadius;
  }
}
