    armHeight: requirePositive(options.armHeight ?? DEFAULT_ARM_HEIGHT, 'Spinner arm height'),
    hubRadius: Math.max(0, options.hubRadius ?? DEFAULT_HUB_RADIUS),
  };
}

function buildSpinnerParts(shape: SpinnerShape): ObstaclePart[] {
  const parts = buildRadialParts({
    axis: shape.axis,
    count: shape.armCount,
    length: shape.armLength,
    width: shape.armWidth,
    depth: shape.armHeight,
    innerRadius: shape.hubRadius,
    namePrefix: 'arm',
  });
  if (shape.hubRadius > 0) {
    parts.push(buildHubPart({ axis: shape.axis, radius: shape.hubRadius, depth: shape.armHeight * 1.4 }));
  }
  return parts;
}

/** Flat spinner sweeping across the putting surface around a vertical axis. */
export class Spinner extends RotatingObstacle {
  readonly armCount: number;
  readonly armLength: number;
  readonly armWidth: number;
  readonly armHeight: number;
  readonly hubRadius: number;

  constructor(options: SpinnerOptions) {
    const shape = resolveShape(options);
    super('spinner', { ...options, axis: shape.axis }, buildSpinnerParts(shape));
    this.armCount = shape.armCount;
    this.armLength = shape.armLength;
    this.armWidth = shape.armWidth;
    this.armHeight = shape.armHeight;
    this.hubRadius = shape.hubRadius;
  }
}
