import RAPIER from '@dimforge/rapier3d-compat';
import type { Quat, Vec3 } from '../contracts/math';
import { CollisionLayers, collisionGroups } from '../physics/CollisionLayers';
import type { PhysicsWorld } from '../physics/PhysicsWorld';
import type { ObstacleBody, ObstacleBodyFactory, ObstacleColliderDescriptor } from './types';

export const OBSTACLE_COLLISION_GROUPS = collisionGroups(
  CollisionLayers.OBSTACLE,
  CollisionLayers.BALL | CollisionLayers.COURSE | CollisionLayers.OBSTACLE,
);

const OBSTACLE_FRICTION = 0.5;

/** Kinematic Rapier body driven by a rotating obstacle. */
export class RapierObstacleBody implements ObstacleBody {
  constructor(
    private readonly physics: PhysicsWorld,
    readonly body: RAPIER.RigidBody,
    readonly colliders: readonly RAPIER.Collider[],
  ) {}

  setRotation(rotation: Quat): void {
    this.body.setNextKinematicRotation(rotation);
  }

  setEnabled(enabled: boolean): void {
    for (const collider of this.colliders) collider.setEnabled(enabled);
  }

  dispose(): void {
    this.physics.world.removeRigidBody(this.body);
  }
}

export class RapierObstacleBodyFactory implements ObstacleBodyFactory {
  constructor(private readonly physics: PhysicsWorld) {}

  createBody(_id: string, position: Vec3, colliders: readonly ObstacleColliderDescriptor[]): ObstacleBody {
    const world = this.physics.world;
    const body = world.createRigidBody(
      RAPIER.RigidBodyDesc.kinematicPositionBased().setTranslation(position.x, position.y, position.z),
    );
    const created = colliders.map((descriptor) =>
      world.createCollider(
        RAPIER.ColliderDesc.cuboid(descriptor.halfExtents.x, descriptor.halfExtents.y, descriptor.halfExtents.z)
          .setTranslation(descriptor.offset.x, descriptor.offset.y, descriptor.offset.z)
          .setRotation(descriptor.rotation)
          .setFriction(OBSTACLE_FRICTION)
          .setRestitution(descriptor.restitution)
          .setCollisionGroups(OBSTACLE_COLLISION_GROUPS),
        body,
      ),
    );
    return new RapierObstacleBody(this.physics, body, created);
  }
}
