import type * as THREE from 'three';
import type { Hole, MovingObstacle, ObstacleDescriptor } from '../courses/types';
import type { RotatingObstacle } from './RotatingObstacle';
import { Spinner } from './Spinner';
import type { ObstacleBodyFactory } from './types';
import { Windmill } from './Windmill';

export interface RotatingObstacleDeps {
  scene?: THREE.Scene;
  physics?: ObstacleBodyFactory;
  color?: number;
}

const ROTATING_TYPES: ReadonlySet<string> = new Set(['spinner', 'windmill']);
const SPINNER_HUB = 0.25;
const WINDMILL_HUB = 0.35;

export function isRotatingObstacleDescriptor(descriptor: ObstacleDescriptor): descriptor is MovingObstacle {
  return 'motion' in descriptor && descriptor.motion.kind === 'rotate' && ROTATING_TYPES.has(descriptor.type);
}

/** Hub radius that keeps the rendered span equal to the descriptor size. */
function hubRadiusFor(span: number, preferred: number): number {
  return Math.min(preferred, Math.max(span / 12, 0.05));
}

export function createRotatingObstacle(
  descriptor: MovingObstacle,
  deps: RotatingObstacleDeps = {},
): RotatingObstacle {
  if (descriptor.motion.kind !== 'rotate') {
    throw new Error('Obstacle \"' + descriptor.id + '\" does not rotate');
  }
  const base = {
    id: descriptor.id,
    position: descriptor.transform.position,
    axis: descriptor.motion.axis,
    speed: descriptor.motion.speed,
    phase: descriptor.motion.phase ?? 0,
    enabled: descriptor.enabled ?? true,
    scene: deps.scene,
    physics: deps.physics,
    color: deps.color,
  };
  const span = descriptor.size.x;

  switch (descriptor.type) {
    case 'spinner': {
      const hubRadius = hubRadiusFor(span, SPINNER_HUB);
      return new Spinner({
        ...base,
        armCount: 2,
        armLength: span / 2 - hubRadius,
        armHeight: descriptor.size.y,
        armWidth: descriptor.size.z,
        hubRadius,
      });
    }
    case 'windmill': {
      const hubRadius = hubRadiusFor(span, WINDMILL_HUB);
      return new Windmill({
        ...base,
        bladeCount: 4,
        bladeLength: span / 2 - hubRadius,
        bladeDepth: descriptor.size.y,
        bladeWidth: descriptor.size.z,
        hubRadius,
      });
    }
    default:
      throw new Error('Obstacle type \"' + descriptor.type + '\" has no rotating implementation');
  }
}

export function createRotatingObstacles(hole: Hole, deps: RotatingObstacleDeps = {}): RotatingObstacle[] {
  return hole.obstacles
    .filter(isRotatingObstacleDescriptor)
    .map((descriptor) => createRotatingObstacle(descriptor, deps));
}
