import type { Hole } from '../courses/types';
import { createRotatingObstacles, type RotatingObstacleDeps } from './factory';
import type { RotatingObstacle } from './RotatingObstacle';

/** Owns the rotating obstacles of the current hole and steps them together. */
export class RotatingObstacleManager {
  private readonly items: RotatingObstacle[] = [];

  constructor(private readonly deps: RotatingObstacleDeps = {}) {}

  get obstacles(): readonly RotatingObstacle[] {
    return this.items;
  }

  add(obstacle: RotatingObstacle): RotatingObstacle {
    this.items.push(obstacle);
    return obstacle;
  }

  addFromHole(hole: Hole): RotatingObstacle[] {
    const created = createRotatingObstacles(hole, this.deps);
    this.items.push(...created);
    return created;
  }

  update(deltaSeconds: number): void {
    for (const item of this.items) item.update(deltaSeconds);
  }

  setEnabled(enabled: boolean): void {
    for (const item of this.items) item.setEnabled(enabled);
  }

  reset(): void {
    for (const item of this.items) item.reset();
  }

  dispose(): void {
    for (const item of this.items) item.dispose();
    this.items.length = 0;
  }
}
